      {
        "factor": "Death of Ayatollah Ali Khamenei (Feb 28, 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Credible outlets report death, ending the lifetime tenure and promptly activating the succession process."
      },
      {
        "factor": "Assembly of Experts succession mechanism",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constitutional framework allows rapid appointment of a new Leader after vacancy, supporting near-term turnover."
